/**
 * Symbol class for function variables.
 *
 * Symbol Data Usage:
 *   	String stringData - variable comment
 */
public class VariableSymbolDB : SymbolDB {

	private VariableStorage variableStorage;
	private VariableStorageManagerDB variableMgr;
	private SymbolType type;

	/**
	 * Constructs a new VariableSymbol
	 * @param symbolMgr the symbol manager
	 * @param type the symbol type.
	 * @param variableMgr variable storage manager
	 * @param address the address of the symbol (stack address)
	 * @param record the record for the symbol
	 */
	VariableSymbolDB(SymbolManager symbolMgr, SymbolType type,
			VariableStorageManagerDB variableMgr, Address address, DBRecord record) : base(symbolMgr, address, record, record.getKey())
    {
		this.type = type;
		this.variableMgr = variableMgr;
	}

	/* @Override */
	public void setInvalid() {
		base.setInvalid();
		variableStorage = null;
	}

	public VariableStorage getVariableStorage() {
		using (Closeable c = @lock.read())
{
			refreshIfNeeded();
			VariableStorage local = variableStorage;
			if (local == null) {
				local = computeVariableStorage();
			}
			return local;
		}
	}

	private VariableStorage computeVariableStorage() {
		VariableStorage local = variableStorage;
		if (local != null) {
			return local;
		}
		try {
			if (address is OldGenericNamespaceAddress) {
				// old use case for upgrade
				try {
					local = new VariableStorage(symbolMgr.getProgram(),
						((OldGenericNamespaceAddress) address).getGlobalAddress(),
						getDataType().getLength());
				}
				catch (InvalidInputException e) {
					variableStorage = VariableStorage.BAD_STORAGE;
				}
			}
			else {
				local = variableMgr.getVariableStorage(address);
				if (local == null) {
					local = (type != SymbolType.PARAMETER) ? VariableStorage.BAD_STORAGE
							: VariableStorage.UNASSIGNED_STORAGE;
				}
			}
		}
		catch (IOException e) {
			symbolMgr.dbError(e);
		}
		variableStorage = local;
		return local;
	}

	/* @Override */
	public SymbolType getSymbolType() {
		return type;
	}

	/* @Override */
	protected bool refresh(DBRecord rec) {
		bool isValid = base.refresh(rec);
		variableStorage = null;
		return isValid;
	}

	/* @Override */
	public bool equals(object obj) {
		// TODO: not sure what constitutes equality since address will differ
		return obj == this;
	}

	/* @Override */
	public bool delete() {
		using (Closeable c = @lock.write())
{
			if (refreshIfNeeded()) {
				FunctionDB fun = getFunction();
				if (fun != null) {
					fun.doDeleteVariable(this);
				}
				base.delete();
				return true;
			}
			return false;
		}
	}

	/* @Override */
	public Variable getObject() {
		FunctionDB func = getFunction();
		if (func != null) {
			return func.getVariable(this);
		}
		return null;
	}

	/* @Override */
	public bool isPrimary() {
		return false;
	}

	/* @Override */
	public bool isExternal() {
		Symbol parentSymbol = getParentSymbol();
		return parentSymbol != null ? parentSymbol.isExternal() : false;
	}

	public FunctionDB getFunction() {
		return (FunctionDB) symbolMgr.getFunctionManager()
				.getFunction(getParentNamespace().getID());
	}

	/* @Override */
	public ProgramLocation getProgramLocation() {
		Variable var = getObject();
		if (var != null) {
			return new VariableNameFieldLocation(var.getProgram(), var, 0);
		}
		return null;
	}

	/* @Override */
	public bool isValidParent(Namespace parent) {
		// symbol is locked to single function and can't be moved
		return getFunction() == parent;
	}

	private string getParamName() {
		return SymbolUtilities.getDefaultParamName(getOrdinal());
	}

	/* @Override */
	protected string doGetName() {
		if (!refreshIfNeeded()) {
			// TODO: SCR
			return "[Invalid VariableSymbol - Deleted!]";
		}

		if (type == SymbolType.PARAMETER) {
			if (getSource() == SourceType.DEFAULT) {
				return getParamName();
			}
			string storedName = base.doGetName();
			if (SymbolUtilities.isDefaultParameterName(storedName)) {
				return getParamName();
			}
			return storedName;
		}

		VariableStorage storage = getVariableStorage();
		if (storage == null || storage.isBadStorage()) {
			return Function.DEFAULT_LOCAL_PREFIX + "_!BAD!";
		}

		if (getSource() == SourceType.DEFAULT) {
			return SymbolUtilities.getDefaultLocalName(getProgram(), storage, getFirstUseOffset());
		}

		// TODO: we use to check for a default name and regenerate new default name but we should
		// not need to do this if source remains at default

		return base.doGetName();
	}

	/* @Override */
	protected SourceType validateNameSource(string newName, SourceType source) {
		if (SymbolUtilities.isDefaultParameterName(newName)) {
			source = SourceType.DEFAULT;
		}
		SymbolType symType = getSymbolType();
		if (symType == SymbolType.PARAMETER && SymbolUtilities.isDefaultParameterName(newName)) {
			source = SourceType.DEFAULT;
		}
		else if (symType == SymbolType.LOCAL_VAR &&
			SymbolUtilities.isDefaultLocalName(getProgram(), newName, getVariableStorage())) {
			return SourceType.DEFAULT;
		}
		return source;
	}

	public DataType getDataType() {
		DataType dt = symbolMgr.getDataType(getDataTypeId());
		if (dt == null) {
			VariableStorage storage = getVariableStorage();
			if (storage == null) {
				dt = DataType.DEFAULT;
			}
			else if (storage.isVoidStorage()) {
				dt = VoidDataType.dataType;
			}
			else {
				dt = Undefined.getUndefinedDataType(storage.size());
			}
		}
		return dt;
	}

	/**
	 * Change the storage address and data-type associated with this variable symbol.
	 * @param newStorage the new storage
	 * @param dt data-type
	 */
	public void setStorageAndDataType(VariableStorage newStorage, DataType dt) {
		try
{
    using (Closeable c = @lock.write())
    {

			checkDeleted();

			long dataTypeID = symbolMgr.getProgram().getDataTypeManager().getResolvedID(dt);

			variableStorage = newStorage;
			Address newAddr = variableMgr.getVariableStorageAddress(newStorage, true);
			setAddress(newAddr); // this may be the only symbol which changes its address

			if (dataTypeID != getDataTypeId()) {
				setDataTypeId(dataTypeID);
			}
			else {
				symbolMgr.symbolDataChanged(this);
			}
		
    }
}
		catch (IOException e) {
			symbolMgr.dbError(e);
		}
	}

	public int getFirstUseOffset() {
		return type == SymbolType.PARAMETER ? 0 : getVariableOffset();
	}

	public void setFirstUseOffset(int firstUseOffset) {
		if (type == SymbolType.LOCAL_VAR) {
			setVariableOffset(firstUseOffset);
		}
	}

	public int getOrdinal() {
		return type == SymbolType.PARAMETER ? getVariableOffset() : int.MinValue;
	}

	public void setOrdinal(int ordinal) {
		if (type == SymbolType.PARAMETER) {
			setVariableOffset(ordinal);
		}
	}

	/* @Override */
	public int getReferenceCount() {
		return getReferences(null).length;
	}

	/* @Override */
	public Reference[] getReferences(TaskMonitor monitor) {
		using (Closeable c = @lock.read())
{
			refreshIfNeeded();
			ReferenceManager rm = symbolMgr.getReferenceManager();
			return rm.getReferencesTo(getObject());
		}
	}

	/* @Override */
	public bool hasReferences() {
		return getReferences(null).length != 0;
	}

	/**
	 * gets the generic symbol data 2 data.
	 * @return the symbol data
	 */
	protected int getVariableOffset() {
		using (Closeable c = @lock.read())
{
			refreshIfNeeded();
			if (record != null) {
				return record.getIntValue(SymbolDatabaseAdapter.SYMBOL_VAROFFSET_COL);
			}
			return 0;
		}

	}

	/**
	 * Sets the symbol's variable offset. For parameters, this is the ordinal, for locals, it is 
	 * the first use offset
	 * @param offset the value to set as the symbols variable offset. 
	 */
	public void setVariableOffset(int offset) {
		using (Closeable c = @lock.write())
{
			checkDeleted();
			if (record != null) {
				record.setIntValue(SymbolDatabaseAdapter.SYMBOL_VAROFFSET_COL, offset);
				updateRecord();
				symbolMgr.symbolDataChanged(this);
			}
		}
	}

	/**
	 * {@return variable symbol comment}
	 */
	public string getSymbolComment() {
		return @lock.withRead(() => record.getString(SymbolDatabaseAdapter.SYMBOL_COMMENT_COL));
	}

	/**
	 * Update variable symbol comment (no change event is issued)
	 * @param comment variable comment
	 */
	public void setSymbolComment(string comment) {
		using (Closeable c = @lock.write())
{
			checkDeleted();
			record.setString(SymbolDatabaseAdapter.SYMBOL_COMMENT_COL, comment);
			updateRecord();
		}
	}

	/**
	 * Update variable symbol record fields
	 * @param record variable symbol record
	 * @param firstUseOffsetOrOrdinal first use offset or param ordinal (ignored if null)
	 * @param comment variable comment
	 */
	static void setRecordFields(DBRecord record, Integer firstUseOffsetOrOrdinal, string comment) {
		if (firstUseOffsetOrOrdinal != null) {
			record.setIntValue(SymbolDatabaseAdapter.SYMBOL_VAROFFSET_COL, firstUseOffsetOrOrdinal);
		}
		record.setString(SymbolDatabaseAdapter.SYMBOL_COMMENT_COL, comment);
	}
}
